import{_ as t,o as a,c as r,a3 as n}from"./chunks/framework.DQ-7HQaQ.js";const h=JSON.parse('{"title":"Implementation resources","description":"Annotated primary repositories and guides for retrieval, document enrichment, durable execution, and streaming adapters.","frontmatter":{"title":"Implementation resources","description":"Annotated primary repositories and guides for retrieval, document enrichment, durable execution, and streaming adapters."},"headers":[],"relativePath":"research/implementation-resources.md","filePath":"research/implementation-resources.md","lastUpdated":1794376220000}'),s={name:"research/implementation-resources.md"};function i(o,e,l,c,d,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="implementation-resources" tabindex="-1">Implementation resources <a class="header-anchor" href="#implementation-resources" aria-label="Permalink to &quot;Implementation resources&quot;">​</a></h1><p><strong>Reviewed November 5, 2026.</strong> These twelve resources map to concrete implementation boundaries in the <a href="/knowledge-lab/architecture/retrieval">retrieval design</a>, <a href="/knowledge-lab/architecture/ingestion">ingestion DAG</a>, and <a href="/knowledge-lab/architecture/backend">Rust backend</a>. Reuse and evaluation recommendations below are our assessment; project documentation is evidence of capabilities, not comparative performance results. Pin the chosen release or commit before implementation because live documentation and default branches change.</p><h2 id="retrieval-and-sqlite-adapters" tabindex="-1">Retrieval and SQLite adapters <a class="header-anchor" href="#retrieval-and-sqlite-adapters" aria-label="Permalink to &quot;Retrieval and SQLite adapters&quot;">​</a></h2><h3 id="_1-sqlite-core-fts5-and-bounded-graph-queries" tabindex="-1">1. SQLite core: FTS5 and bounded graph queries <a class="header-anchor" href="#_1-sqlite-core-fts5-and-bounded-graph-queries" aria-label="Permalink to &quot;1. SQLite core: FTS5 and bounded graph queries&quot;">​</a></h3><p><strong>Source:</strong> <a href="https://sqlite.org/src" target="_blank" rel="noreferrer">official Fossil repository</a>, with an <a href="https://github.com/sqlite/sqlite" target="_blank" rel="noreferrer">official Git mirror</a>. <strong>Read:</strong> <a href="https://www.sqlite.org/fts5.html" target="_blank" rel="noreferrer">FTS5 BM25 and ranking</a>, <a href="https://www.sqlite.org/lang_with.html" target="_blank" rel="noreferrer">recursive CTE graph examples</a>, and <a href="https://www.sqlite.org/wal.html" target="_blank" rel="noreferrer">WAL concurrency</a>.</p><p>Reuse FTS5 for the lexical baseline and indexed relational edge tables for bounded graph expansion. FTS5&#39;s best BM25 matches have lower numeric scores; <code>rank</code> is useful for ordered retrieval. Keep chunk IDs and source evidence in ordinary tables. Evaluate tokenizer behavior, repeated terms, technical identifiers, graph fanout, and concurrent publication. WAL still has one writer at a time and a same-host operating boundary; a broker does not change those constraints.</p><h3 id="_2-sqlite-vec1-the-sqlite-project-s-ann-candidate" tabindex="-1">2. SQLite Vec1: the SQLite project&#39;s ANN candidate <a class="header-anchor" href="#_2-sqlite-vec1-the-sqlite-project-s-ann-candidate" aria-label="Permalink to &quot;2. SQLite Vec1: the SQLite project&#39;s ANN candidate&quot;">​</a></h3><p><strong>Source:</strong> <a href="https://sqlite.org/src" target="_blank" rel="noreferrer">SQLite source repository</a>. <strong>Read:</strong> <a href="https://www.sqlite.org/vec1.html" target="_blank" rel="noreferrer">Vec1 overview/build instructions</a> and <a href="https://www.sqlite.org/vec1doc.html" target="_blank" rel="noreferrer">the usage manual</a>.</p><p>Evaluate Vec1 as a separately compiled extension; do not assume stock SQLite includes it. The overview identifies release <strong>0.8</strong>. The manual distinguishes exhaustive modes from trained IVFADC/OPQ ANN and explains candidate reranking, metadata predicates, and streaming post-filter queries. Reuse those examples to test our eligibility filters against an exact reference set. ANN training, update behavior, recall, and query shape belong in the adapter evaluation. Vec1&#39;s SQL streaming candidates are unrelated to browser SSE or resumable model generation.</p><h3 id="_3-sqlite-vec-exact-baseline-and-a-separate-prerelease-experiment" tabindex="-1">3. sqlite-vec: exact baseline and a separate prerelease experiment <a class="header-anchor" href="#_3-sqlite-vec-exact-baseline-and-a-separate-prerelease-experiment" aria-label="Permalink to &quot;3. sqlite-vec: exact baseline and a separate prerelease experiment&quot;">​</a></h3><p><strong>Source:</strong> <a href="https://github.com/asg017/sqlite-vec" target="_blank" rel="noreferrer">asg017/sqlite-vec</a>. <strong>Read:</strong> <a href="https://github.com/asg017/sqlite-vec/releases" target="_blank" rel="noreferrer">release notes</a>, <a href="https://alexgarcia.xyz/sqlite-vec/features/knn.html" target="_blank" rel="noreferrer">KNN queries</a>, and <a href="https://alexgarcia.xyz/sqlite-vec/features/vec0.html" target="_blank" rel="noreferrer">metadata/partition keys</a>.</p><p>The reviewed release page marks <strong>v0.1.9</strong> as the latest stable release and <strong>v0.1.10-alpha.4</strong> as a prerelease. Preserve that distinction in experiments:</p><table tabindex="0"><thead><tr><th>Channel</th><th>Study purpose</th></tr></thead><tbody><tr><td>v0.1.9 stable</td><td>Flat/exact KNN baseline and supported filtering</td></tr><tr><td>v0.1.10 alpha series</td><td>DiskANN/rescore experiment; initial IVF support was described as experimental and not enabled</td></tr></tbody></table><p>Reuse <code>vec0</code> examples and partition-aware queries. Do not extrapolate flat-index filtering behavior to an ANN release without checking it. Metadata operators and auxiliary columns have documented restrictions. The project remains pre-v1, and release notes acknowledge stale documentation, so release-specific tests must settle behavior.</p><h3 id="_4-sqlite-vector-ordinary-table-and-quantized-scan-alternative" tabindex="-1">4. SQLite-Vector: ordinary-table and quantized-scan alternative <a class="header-anchor" href="#_4-sqlite-vector-ordinary-table-and-quantized-scan-alternative" aria-label="Permalink to &quot;4. SQLite-Vector: ordinary-table and quantized-scan alternative&quot;">​</a></h3><p><strong>Source:</strong> <a href="https://github.com/sqliteai/sqlite-vector" target="_blank" rel="noreferrer">sqliteai/sqlite-vector</a>. <strong>Read:</strong> <a href="https://github.com/sqliteai/sqlite-vector/blob/main/API.md" target="_blank" rel="noreferrer">API reference</a> and <a href="https://github.com/sqliteai/sqlite-vector/blob/main/QUANTIZATION.md" target="_blank" rel="noreferrer">quantization/recall examples</a>.</p><p>Keep this as a secondary comparison if ordinary <code>BLOB</code> columns, compact representations, or scan memory become useful. It exposes exact scans and quantized scans, including low-bit options. Quantized approximate distances are a different tradeoff from a graph-based ANN index; compare recall and filtered query behavior explicitly. Its quantization guide includes exact-versus-approximate recall measurement. The repository&#39;s <a href="https://github.com/sqliteai/sqlite-vector/blob/main/LICENSE.md" target="_blank" rel="noreferrer">license</a> is Apache-2.0. Do not carry its promotional speed or memory figures into our capacity plan without reproducing them on our corpus.</p><h2 id="parsing-linguistic-annotation-and-entity-candidates" tabindex="-1">Parsing, linguistic annotation, and entity candidates <a class="header-anchor" href="#parsing-linguistic-annotation-and-entity-candidates" aria-label="Permalink to &quot;Parsing, linguistic annotation, and entity candidates&quot;">​</a></h2><h3 id="_5-docling-structured-conversion-and-contextual-chunking" tabindex="-1">5. Docling: structured conversion and contextual chunking <a class="header-anchor" href="#_5-docling-structured-conversion-and-contextual-chunking" aria-label="Permalink to &quot;5. Docling: structured conversion and contextual chunking&quot;">​</a></h3><p><strong>Source:</strong> <a href="https://github.com/docling-project/docling" target="_blank" rel="noreferrer">docling-project/docling</a>. <strong>Read:</strong> <a href="https://docling-project.github.io/docling/concepts/chunking/" target="_blank" rel="noreferrer">chunking concepts</a>, <a href="https://docling-project.github.io/docling/_generated/examples/hybrid_chunking/" target="_blank" rel="noreferrer">hybrid chunking example</a>, and <a href="https://docling-project.github.io/docling/usage/enrichments/" target="_blank" rel="noreferrer">optional enrichments</a>.</p><p>Evaluate <code>DoclingDocument</code> and <code>HybridChunker</code> for the first parser adapter. The chunker refines structural chunks against a supplied tokenizer and can include contextual metadata; table headers can be preserved across chunks. Reuse the example&#39;s separation of chunk content and contextualized serialization, while retaining original source anchors. Test actual PDFs, tables, headings, OCR, and code. Optional enrichment adds model work and should have independent readiness/budgets. The repository states that code is MIT-licensed and individual models have their own licenses.</p><h3 id="_6-spacy-linguistic-pipeline-plus-explicit-entity-linking-contracts" tabindex="-1">6. spaCy: linguistic pipeline plus explicit entity-linking contracts <a class="header-anchor" href="#_6-spacy-linguistic-pipeline-plus-explicit-entity-linking-contracts" aria-label="Permalink to &quot;6. spaCy: linguistic pipeline plus explicit entity-linking contracts&quot;">​</a></h3><p><strong>Source:</strong> <a href="https://github.com/explosion/spaCy" target="_blank" rel="noreferrer">explosion/spaCy</a>. <strong>Read:</strong> <a href="https://spacy.io/usage/linguistic-features" target="_blank" rel="noreferrer">linguistic annotations and named entities</a> and <a href="https://spacy.io/api/entitylinker" target="_blank" rel="noreferrer">EntityLinker requirements</a>.</p><p>Reuse sentence/token annotations, domain rules, and span-based NER as one baseline. The linker is particularly relevant to our data model: it requires a knowledge base, plausible candidate generation, and a context-based selection model. This makes a useful adapter contract for canonical entity resolution, rather than treating an extracted name as an identity. Evaluate language/model fit, ambiguous acronyms, unseen entities, and abstention. Preserve offsets through normalization and keep mention detection, coreference, and canonical identity decisions distinct.</p><h3 id="_7-gliner-schema-selected-mention-extraction" tabindex="-1">7. GLiNER: schema-selected mention extraction <a class="header-anchor" href="#_7-gliner-schema-selected-mention-extraction" aria-label="Permalink to &quot;7. GLiNER: schema-selected mention extraction&quot;">​</a></h3><p><strong>Source:</strong> <a href="https://github.com/urchade/GLiNER" target="_blank" rel="noreferrer">urchade/GLiNER</a>. <strong>Read:</strong> <a href="https://urchade.github.io/GLiNER/quickstart.html" target="_blank" rel="noreferrer">quickstart with inference-time labels</a> and <a href="https://urchade.github.io/GLiNER/" target="_blank" rel="noreferrer">current framework documentation</a>.</p><p>Evaluate GLiNER against spaCy&#39;s baseline for domain concepts that fixed general NER labels miss. Reuse the text-plus-labels extraction interface, persist spans and model/version information, and measure precision/recall on annotated corpus samples. Current documentation also covers relation extraction and streaming architectures; these are optional experiments, not a requirement to replace every ingestion stage. Entity extraction output still needs our identity-resolution and evidence-validation process. The code <a href="https://github.com/urchade/GLiNER/blob/main/LICENSE" target="_blank" rel="noreferrer">license is Apache-2.0</a>; select and record the particular checkpoint separately.</p><h2 id="rust-serving-and-event-adapters" tabindex="-1">Rust serving and event adapters <a class="header-anchor" href="#rust-serving-and-event-adapters" aria-label="Permalink to &quot;Rust serving and event adapters&quot;">​</a></h2><h3 id="_8-async-nats-jetstream-publication-and-consumer-examples" tabindex="-1">8. async-nats: JetStream publication and consumer examples <a class="header-anchor" href="#_8-async-nats-jetstream-publication-and-consumer-examples" aria-label="Permalink to &quot;8. async-nats: JetStream publication and consumer examples&quot;">​</a></h3><p><strong>Source:</strong> <a href="https://github.com/nats-io/nats.rs" target="_blank" rel="noreferrer">nats-io/nats.rs</a>. <strong>Read:</strong> <a href="https://docs.rs/async-nats/latest/async_nats/jetstream/index.html" target="_blank" rel="noreferrer">JetStream examples</a>, <a href="https://docs.rs/async-nats/latest/async_nats/jetstream/context/struct.Context.html#method.publish" target="_blank" rel="noreferrer">publish acknowledgment API</a>, and <a href="https://docs.nats.io/learn/jetstream/delivery-and-acknowledgment" target="_blank" rel="noreferrer">delivery/redelivery guide</a>.</p><p>Reuse the asynchronous client behind an event-publication adapter. A concrete detail to retain: <code>publish(...).await</code> returns an acknowledgment future; awaiting the server acknowledgment is a separate step. Consumers commit idempotently before acknowledging and tolerate redelivery. Study connection loss, bounded pulls, acknowledgment deadlines, and outbox reconciliation. JetStream delivery guarantees do not make database writes and external inference one atomic operation. Internal DAG scheduling remains owned by the selected orchestrator.</p><h3 id="_9-axum-tokio-direct-sse-and-supervised-request-work" tabindex="-1">9. Axum/Tokio: direct SSE and supervised request work <a class="header-anchor" href="#_9-axum-tokio-direct-sse-and-supervised-request-work" aria-label="Permalink to &quot;9. Axum/Tokio: direct SSE and supervised request work&quot;">​</a></h3><p><strong>Source:</strong> <a href="https://github.com/tokio-rs/axum" target="_blank" rel="noreferrer">tokio-rs/axum</a>, alongside <a href="https://github.com/tokio-rs/tokio" target="_blank" rel="noreferrer">tokio-rs/tokio</a>. <strong>Read:</strong> <a href="https://docs.rs/axum/latest/axum/response/sse/index.html" target="_blank" rel="noreferrer">Axum SSE example</a>, <a href="https://tokio.rs/tokio/topics/shutdown" target="_blank" rel="noreferrer">Tokio shutdown</a>, and <a href="https://docs.rs/tokio/latest/tokio/task/fn.spawn_blocking.html" target="_blank" rel="noreferrer">blocking-task constraints</a>.</p><p>Reuse SSE event/keepalive primitives and cancellation/task-tracking patterns for the first browser-to-Rust slice. Add our versioned event schema, authenticated commands, run sequencing, and bounded buffers around them. The SSE helper does not supply replay or durable run ownership. SQLite work needs bounded database threads; already-started blocking tasks cannot be aborted simply by aborting their join handle. Test partial delivery, slow clients, cancellation, and proxy buffering before connecting a model provider.</p><h2 id="durable-dag-execution-evaluate-one-owner" tabindex="-1">Durable DAG execution: evaluate one owner <a class="header-anchor" href="#durable-dag-execution-evaluate-one-owner" aria-label="Permalink to &quot;Durable DAG execution: evaluate one owner&quot;">​</a></h2><h3 id="_10-dagster-assets-dependencies-and-selective-reprocessing" tabindex="-1">10. Dagster: assets, dependencies, and selective reprocessing <a class="header-anchor" href="#_10-dagster-assets-dependencies-and-selective-reprocessing" aria-label="Permalink to &quot;10. Dagster: assets, dependencies, and selective reprocessing&quot;">​</a></h3><p><strong>Source:</strong> <a href="https://github.com/dagster-io/dagster" target="_blank" rel="noreferrer">dagster-io/dagster</a>. <strong>Read:</strong> <a href="https://dagster.io/docs/guides/build/assets/modeling-etl-pipelines" target="_blank" rel="noreferrer">modeling ETL as assets</a> and <a href="https://dagster.io/docs/guides/build/partitions-and-backfills/partitioning-assets" target="_blank" rel="noreferrer">partitioning assets</a>.</p><p>Prototype source revision, parsed document, chunks, annotations, and published projections as assets. Reuse dependency and partition examples to study lineage and backfills. The ETL guide explicitly discusses the tradeoff between one operation and independently materializable phases; schedule meaningful artifacts or batches. Asset metadata is not automatically our source-of-truth publication transaction. Evaluate correction/reprocessing behavior, partition cardinality, operational storage, and recovery before selecting Dagster.</p><h3 id="_11-temporal-python-sdk-recoverable-per-document-execution" tabindex="-1">11. Temporal Python SDK: recoverable per-document execution <a class="header-anchor" href="#_11-temporal-python-sdk-recoverable-per-document-execution" aria-label="Permalink to &quot;11. Temporal Python SDK: recoverable per-document execution&quot;">​</a></h3><p><strong>Source:</strong> <a href="https://github.com/temporalio/sdk-python" target="_blank" rel="noreferrer">temporalio/sdk-python</a>. <strong>Read:</strong> <a href="https://docs.temporal.io/develop/python/workflows/basics" target="_blank" rel="noreferrer">workflow basics</a> and <a href="https://docs.temporal.io/develop/python" target="_blank" rel="noreferrer">SDK guide</a>.</p><p>Prototype a document-revision workflow with parsing, NLP, embedding, and publication as activities. Study cancellation, retries, workflow versioning, and worker restarts. Workflow code must remain deterministic; model calls, file access, and other external work belong in activities. Activity retries still require our idempotency/version checks. Keep large artifacts in artifact storage and pass references. Temporal needs its service and workflow-state infrastructure, separate from retrieval SQLite. Compare the same failure scenarios with Dagster; the architecture has not selected either engine.</p><h2 id="browser-adapter" tabindex="-1">Browser adapter <a class="header-anchor" href="#browser-adapter" aria-label="Permalink to &quot;Browser adapter&quot;">​</a></h2><h3 id="_12-sveltekit-initial-state-and-independently-updated-chat-panels" tabindex="-1">12. SvelteKit: initial state and independently updated chat panels <a class="header-anchor" href="#_12-sveltekit-initial-state-and-independently-updated-chat-panels" aria-label="Permalink to &quot;12. SvelteKit: initial state and independently updated chat panels&quot;">​</a></h3><p><strong>Source:</strong> <a href="https://github.com/sveltejs/kit" target="_blank" rel="noreferrer">sveltejs/kit</a>, with <a href="https://github.com/sveltejs/svelte" target="_blank" rel="noreferrer">sveltejs/svelte</a>. <strong>Read:</strong> <a href="https://svelte.dev/docs/kit/page-options" target="_blank" rel="noreferrer">rendering options</a>, <a href="https://svelte.dev/docs/kit/state-management" target="_blank" rel="noreferrer">server/client state guidance</a>, and <a href="https://svelte.dev/docs/svelte/$state" target="_blank" rel="noreferrer">granular state updates</a>.</p><p>Reuse routing, per-route rendering choices, and request-scoped SSR state. Implement the <a href="/knowledge-lab/architecture/frontend">frontend design</a> against our Rust event contract: authorized snapshot, sequence/attempt validation, incremental answer, and independent source/status panels. Rendering helpers do not provide a resumable chat protocol. Keep streaming Markdown, graph exploration, and document viewers behind separate interfaces and performance tests; this resource does not settle those library choices.</p><h2 id="first-implementation-study-order" tabindex="-1">First implementation study order <a class="header-anchor" href="#first-implementation-study-order" aria-label="Permalink to &quot;First implementation study order&quot;">​</a></h2><ol><li><strong>Prove the chat boundary:</strong> Axum SSE plus SvelteKit, using deterministic fixture events to test sources, Stop, disconnect, duplicate sequences, and resynchronization.</li><li><strong>Prove evidence locations:</strong> Docling conversion/chunking on representative source formats; inspect anchors before adding generated augmentation.</li><li><strong>Establish retrieval truth:</strong> FTS5 plus exact vector search, with tenant/ACL filters, canonical IDs, and fixed relevance examples.</li><li><strong>Measure alternatives:</strong> Vec1 ANN, sqlite-vec&#39;s separate alpha experiment, and SQLite-Vector only where justified; compare recall, filtered latency, concurrent ingestion, and native failure behavior.</li><li><strong>Evaluate enrichment independently:</strong> spaCy versus GLiNER mentions, then KB candidate generation/linking, source-backed claims, and reversible corrections.</li><li><strong>Choose execution semantics:</strong> run the same document update, crash, retry, deletion, and backfill scenario in Dagster and Temporal; choose one progression owner, then integrate committed boundary events through async-nats.</li></ol><p>Record versions, configuration, corpus, correctness results, and timings for each experiment. These studies are planned work; no package installation, integration, or comparative benchmark is represented as completed here.</p>',48)])])}const g=t(s,[["render",i]]);export{h as __pageData,g as default};
